<template><view class="shop-page"><BusinessPageHeader title="订单详情" fallback="/pages/profile/index"/><view class="shop-body"><FeaturePageState :status="status" :error="error" @retry="load"/><template v-if="data"><view class="shop-card shop-status"><image :src="data.order.status==='PENDING_PAYMENT'?'/static/profile/icon-order-payment.png':'/static/profile/icon-order-completed.png'" mode="aspectFit"/><view><view class="shop-title">订单{{data.order.statusLabel}}</view><text class="shop-muted">{{subtitle}}</text></view></view><view v-if="data.order.address" class="shop-card"><view class="shop-title">{{data.order.address.recipient}} {{data.order.address.phone}}</view><text class="shop-muted">{{data.order.address.regionNames?.join('')}} {{data.order.address.detail}}</text></view><view v-if="data.order.memberName" class="shop-card"><text class="shop-muted">会员</text><view class="shop-title">{{data.order.memberName}}</view></view><view class="shop-card"><view class="shop-title">{{data.order.store.name}} <text class="shop-tag">{{data.order.store.number}}</text></view><text class="shop-muted">{{data.order.store.address}}</text></view><view class="shop-card"><view class="shop-title">共{{data.order.items.reduce((sum,x)=>sum+x.quantity,0)}}件商品</view><view v-for="line in data.order.items" :key="line.id" class="shop-product-line"><image :src="line.coverUrl" mode="aspectFill"/><view><view>{{line.title}}</view><text class="shop-tag">{{line.specLabel}}</text><view class="shop-muted">×{{line.quantity}}</view></view><text class="shop-price">¥{{money(line.unitAmount)}}</text></view><view class="shop-row"><text>订单备注</text><text>{{data.order.remark||'暂无备注'}}</text></view><view class="shop-row"><text>商品金额</text><text>¥{{money(data.order.goodsAmount)}}</text></view><view class="shop-row"><text>优惠券</text><text>−¥{{money(data.order.discountAmount)}}</text></view><view class="shop-row"><text>总计</text><text class="shop-price">¥{{money(data.order.payableAmount)}}</text></view></view><view class="shop-card"><view class="shop-title">订单信息</view><view class="shop-row"><text>订单编号</text><button class="shop-link" @click="copyNumber">{{data.order.orderNo}} 复制</button></view><view v-for="field in timeFields" :key="field.key" class="shop-row"><text>{{field.label}}</text><text>{{businessDateLabel(data.order[field.key])}}</text></view><view v-if="data.order.trackingNo" class="shop-row"><text>物流单号</text><text>{{data.order.trackingNo}}</text></view></view><text v-if="actionError" class="shop-error">{{actionError}}</text></template></view><view v-if="data?.order.allowedActions.length" class="shop-footer"><view>合计：<text class="shop-price">¥{{money(data.order.payableAmount)}}</text></view><button v-if="can('cancel')" class="shop-secondary" :disabled="busy" @click="act('cancel')">取消订单</button><button v-if="can('pay')" class="shop-primary" @click="pay">去支付</button><button v-if="can('confirm-receipt')" class="shop-primary" :disabled="busy" @click="act('confirm-receipt')">确认收货</button></view></view></template>
<script setup>
import {ref,computed} from 'vue'
import {onLoad,onShow,onUnload} from '@dcloudio/uni-app'
import {useAuth} from '../../composables/useAuth'
import {useAsyncPage} from '../../composables/useAsyncPage'
import {getCommerceOrder,changeOrder,commerceRequestKey} from '../../services/commerce'
import {money} from '../../features/exclusive/format'
import {businessDateLabel} from '../../features/business/format'
import BusinessPageHeader from '../../components/BusinessPageHeader.vue'
import FeaturePageState from '../../components/FeaturePageState.vue'
useAuth();let id='',contextId='',active=true,operation=null;const busy=ref(false),actionError=ref(''),{data,status,error,load}=useAsyncPage(()=>getCommerceOrder(id,contextId),false),can=action=>data.value?.order.allowedActions.includes(action)
const subtitle=computed(()=>{const o=data.value?.order;if(!o)return '';if(o.status==='CANCELLED')return '订单已关闭';if(o.status==='PENDING_PAYMENT')return '请在有效期内完成支付';if(o.fulfillmentType==='PHYSICAL')return o.trackingNo?`顺丰快递 ${o.trackingNo}`:'您的订单等待发货，请耐心等待';if(o.fulfillmentType==='ACTIVATION_CODE'||o.fulfillmentType==='COLUMN_ACCESS')return '请联系所属门店获取激活码';return '该单为线下交付产品，请前往门店使用'}),timeFields=computed(()=>[{key:'createdAt',label:'下单时间'},{key:'paidAt',label:'支付时间'},{key:'cancelledAt',label:'取消时间'},{key:'receivedAt',label:'收货时间'}].filter(x=>data.value?.order[x.key]))
function pay(){uni.navigateTo({url:`/pages/payment/cashier?orderId=${encodeURIComponent(id)}`})}
function copyNumber(){uni.setClipboardData({data:data.value.order.orderNo})}
async function act(action){if(busy.value)return;const confirmed=await new Promise(resolve=>uni.showModal({title:action==='cancel'?'取消订单':'确认收货',content:action==='cancel'?'确定要取消该订单吗？':'确认已经收到商品？',success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!confirmed||busy.value)return;busy.value=true;actionError.value='';const version=data.value.order.version;if(!operation||operation.action!==action||operation.version!==version)operation={action,version,key:commerceRequestKey()};try{await changeOrder(id,action,version,operation.key);if(active){operation=null;await load()}}catch(e){if(active)actionError.value=e.message}finally{if(active)busy.value=false}}
onLoad(q=>{id=q.id||'';contextId=q.contextId||''});onShow(load);onUnload(()=>{active=false})
</script><style>@import '../../styles/commerce.css';</style>
